payments = [{'amount':0},{'amount':-5},{'amount':'x','method':'card'},{'amount':30,'method':'card'},{'amount':40,'method':'card'},{'amount':55,'method':'card'},{'amount':60,'method':'card'},{'amount':100,'method':'cash'},{'amount':None,'method':'card'}, {'method':'card'}, {'amount':40}]
